import { systemClock } from './clock';
import type { Clock } from './clock';

// Fixed-window rate limiter.
export interface LimiterOptions {
  limit: number;
  windowMs: number;
}

export class RateLimiter {
  private readonly options: LimiterOptions;
  private readonly clock: Clock;
  private counts = new Map<string, number>();
  private windowStart = 0;

  constructor(options: LimiterOptions, clock: Clock = systemClock) {
    this.options = options;
    this.clock = clock;
  }

  allow(key: string): boolean {
    this.roll();
    const used = this.counts.get(key) ?? 0;
    if (used >= this.options.limit) {
      return false;
    }
    this.counts.set(key, used + 1);
    return true;
  }

  private roll(): void {
    const t = this.clock.now();
    if (t - this.windowStart >= this.options.windowMs) {
      this.windowStart = t;
      this.counts.clear();
    }
  }
}

export const DEFAULT_OPTIONS: LimiterOptions = { limit: 10, windowMs: 1000 };

