import { systemClock } from './clock';
import type { Clock } from './clock';
import { notifyRejected } from './notify';

// Fixed-window rate limiter with a per-key burst allowance.
export interface LimiterOptions {
  limit: number;
  windowMs: number;
  burst?: number;
}

export class RateLimiter {
  private readonly options: LimiterOptions;
  private readonly clock: Clock;
  private counts = new Map<string, number>();
  private windowStart = 0;
  private rejected = 0;

  constructor(options: LimiterOptions, clock: Clock = systemClock) {
    this.options = options;
    this.clock = clock;
  }

  allow(key: string): boolean {
    this.roll();
    const used = this.counts.get(key) ?? 0;
    const cap = this.options.limit + (this.options.burst ?? 0);
    if (used >= cap) {
      this.rejected += 1;
      notifyRejected(key, this.rejected);
      return false;
    }
    this.counts.set(key, used + 1);
    return true;
  }

  private roll(): void {
    const t = this.clock.now();
    if (t - this.windowStart >= this.options.windowMs) {
      this.windowStart = t;
      this.counts.clear();
      this.rejected = 0;
    }
  }
}

export const DEFAULT_OPTIONS: LimiterOptions = { limit: 10, windowMs: 1000 };

export function retryAfterMs(elapsedMs: number, windowMs: number, used: number, cap: number): number {
  if (used < cap) {
    return 0;
  }
  if (elapsedMs >= windowMs || windowMs <= 0) {
    return 0;
  }
  const remaining = windowMs - elapsedMs;
  return used > cap * 2 ? windowMs : remaining;
}

